/**
 * PHOTOGRAPHY GALLERY
 * ---------------------------------------------------------------------------
 * ⚠ All images are PLACEHOLDERS generated by scripts/generate-placeholders.mjs.
 * Replace `src`, `width`, `height` and `alt` with real photographs.
 * Width/height should be the real pixel size (prevents layout shift).
 */

export const galleryCategories = [
  "Portraits",
  "Fashion",
  "Editorial",
  "Lifestyle",
  "Events",
  "Creative",
] as const;

export type GalleryCategory = (typeof galleryCategories)[number];

export type GalleryImage = {
  src: string;
  width: number;
  height: number;
  alt: string;
  category: GalleryCategory;
  caption?: string;
  placeholder: boolean;
};

const g = (file: string, width: number, height: number, category: GalleryCategory): GalleryImage => ({
  src: `/images/gallery/${file}.jpg`,
  width,
  height,
  category,
  alt: `Placeholder — ${category} photograph`,
  caption: `${category} — sample frame`,
  placeholder: true,
});

export const gallery: GalleryImage[] = [
  g("portraits-01", 1600, 2000, "Portraits"),
  g("editorial-01", 2100, 1400, "Editorial"),
  g("fashion-01", 1400, 2100, "Fashion"),
  g("lifestyle-01", 1800, 1800, "Lifestyle"),
  g("events-01", 2100, 1400, "Events"),
  g("creative-01", 1400, 2100, "Creative"),
  g("portraits-02", 1800, 1800, "Portraits"),
  g("editorial-02", 2400, 1350, "Editorial"),
  g("fashion-02", 1600, 2000, "Fashion"),
  g("lifestyle-02", 1600, 2000, "Lifestyle"),
  g("creative-02", 2100, 1400, "Creative"),
  g("events-02", 1400, 2100, "Events"),
];
